  glossary: [
    { term: 'STP', definition: { pt: 'Segmentation, Targeting, Positioning. O funil de 3 etapas para escolher clientes e uma posição.', en: 'Segmentation, Targeting, Positioning. The 3-step funnel to pick customers and a position.' } },
    { term: 'Market segmentation', definition: { pt: 'Dividir o mercado grande e heterogêneo em subconjuntos homogêneos (segmentos).', en: 'Dividing the big, heterogeneous market into homogeneous subsets (segments).' } },
    { term: 'Segment', definition: { pt: 'Um grupo de clientes com desejos, recursos e hábitos parecidos, que pode ser escolhido como alvo.', en: 'A group of customers with similar wants, resources and habits, which can be selected as a target.' } },
    { term: 'Geographic', definition: { pt: 'Base de segmentação por local: nação, região, cidade, bairro, clima. (ONDE mora)', en: 'Segmentation base by location: nation, region, city, neighbourhood, climate. (WHERE they live)' } },
    { term: 'Demographic', definition: { pt: 'Base mais popular: idade, gênero, renda. Fácil de medir e boa previsora do consumo. (QUEM é)', en: 'Most popular base: age, gender, income. Easy to measure and a good predictor of consumption. (WHO they are)' } },
    { term: 'Psychographic', definition: { pt: 'Base por classe social, estilo de vida, personalidade e valores. (COMO PENSA)', en: 'Base by social class, lifestyle, personality and values. (HOW they think)' } },
    { term: 'Behavioural', definition: { pt: 'Base por comportamento: ocasião, benefício buscado, status de usuário, taxa de uso, lealdade. (COMO AGE)', en: 'Base by behaviour: occasion, benefit sought, user status, usage rate, loyalty. (HOW they act)' } },
    { term: 'Target market', definition: { pt: 'Conjunto de compradores com necessidades/características comuns que a empresa decide servir.', en: 'Set of buyers with common needs/characteristics the firm decides to serve.' } },
    { term: 'Undifferentiated / Mass', definition: { pt: 'Mira o mercado todo com uma oferta só; foca no que é comum. O mais barato.', en: 'Targets the whole market with one offer; focuses on what is common. The cheapest.' } },
    { term: 'Differentiated', definition: { pt: 'Vários segmentos, uma oferta separada pra cada. Mais vendas, porém mais caro.', en: 'Several segments, a separate offer for each. Higher sales, but more expensive.' } },
    { term: 'Concentrated / Niche', definition: { pt: 'Grande fatia de um segmento pequeno. Domina o nicho.', en: 'Large share of one small segment. Dominates the niche.' } },
    { term: 'Micromarketing', definition: { pt: 'Sob medida para locais (local) e indivíduos (individual, 1-a-1).', en: 'Tailored to locations (local) and individuals (individual, 1-to-1).' } },
    { term: 'DAMAS (critérios)', definition: { pt: 'Distinct, Accessible, Measurable, Actionable, Substantial. 5 filtros para avaliar se um segmento vale a pena antes de investir.', en: 'Distinct, Accessible, Measurable, Actionable, Substantial. 5 filters to assess whether a segment is worth it before investing.' } },
    { term: 'Actionable (DAMAS)', definition: { pt: 'A empresa tem capacidade + verba pra servir o segmento com lucro. Espelha a regra de ouro do SWOT (força interna).', en: 'The firm has the capability + budget to serve the segment profitably. Mirrors the SWOT golden rule (internal strength).' } },
    { term: 'Positioning', definition: { pt: 'Como o produto é definido pelos consumidores em atributos importantes — o lugar dele na mente.', en: 'How the product is defined by consumers on important attributes — its place in the mind.' } },
    { term: 'Positioning statement', definition: { pt: '“Para [alvo] que [necessidade], a [marca] é a [conceito] que [diferencial].”', en: '“For [target] who [need], [brand] is the [concept] that [differentiator].”' } },
    { term: 'Perceptual map', definition: { pt: 'Diagrama de 2 eixos que mostra onde as marcas “moram” na mente do cliente.', en: '2-axis diagram showing where brands “live” in the customer\'s mind.' } },
    { term: 'Repositioning', definition: { pt: 'Mudar de propósito a posição de uma marca (ex: Lucozade, de remédio a bebida esportiva).', en: 'Deliberately changing a brand\'s position (e.g. Lucozade, from remedy to sports drink).' } },
    { term: 'Value proposition', definition: { pt: 'A promessa de valor que justifica por que o cliente-alvo deve escolher a marca.', en: 'The promise of value that justifies why the target customer should choose the brand.' } },
    { term: 'CLV (Customer Lifetime Value)', definition: { pt: 'Receita média que um cliente traz ao longo de toda a relação. Mire quem tem o maior CLV.', en: 'Average revenue a customer brings over the whole relationship. Target the highest CLV.' } },
    { term: 'Pareto (80/20)', definition: { pt: 'Regra da segmentação: ~80% do lucro vem de ~20% dos clientes/segmentos. Foca neles.', en: 'Segmentation rule: ~80% of profit comes from ~20% of customers/segments. Focus on them.' } },
    { term: 'Shotgun vs targeted', definition: { pt: '“Espingarda” = falar com todo mundo (desperdício). STP = tiro seletivo, recurso eficiente.', en: '“Shotgun” = talk to everyone (waste). STP = selective fire, efficient resources.' } },
    { term: 'USP (Unique Selling Point)', definition: { pt: 'O motivo pra te escolher em vez do concorrente — o coração do posicionamento.', en: 'The reason to choose you over the competitor — the heart of positioning.' } },
    { term: 'Top of mind', definition: { pt: 'Ser a 1ª marca que vem à cabeça do cliente diante de uma “dor” — o objetivo do posicionamento.', en: 'Being the 1st brand that comes to the customer\'s mind for a “pain point” — the goal of positioning.' } },
    { term: '4 Ps (marketing mix)', definition: { pt: 'Product, Price, Promotion, Place. Definidos DEPOIS do STP: cada segmento tem seu próprio mix.', en: 'Product, Price, Promotion, Place. Set AFTER STP: each segment has its own mix.' } }
  ],
